insert into public.site_content (key, value) values ('hero', '{"title":"Ku gjuha hap botën.","lede":"Gjimnaz i shkencave shoqërore-gjuhësore në Prishtinë, me emrin e gjuhëtarit Eqrem Çabej.","image_url":"/media/diplomimi-germia.webp","image_alt":"Maturantët hedhin kapelet në ceremoninë e diplomimit.","primary_cta":{"label":"Njihu me programet","href":"/programet"},"secondary_cta":{"label":"Lajmet","href":"/lajme"}}'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('intro', '{"heading":"Një shkollë e ndërtuar rreth gjuhës.","body":"Që nga viti 1990 shkolla është profilizuar në gjuhë. Sot është gjimnaz i shkencave shoqërore-gjuhësore dhe pjesë e Programit të Diplomës Gjermane që nga viti 2002–2003.","vision":"Të bëhet shkollë elitare dhe gjithëpërfshirëse.","mission":"Të kontribuojë në zhvillimin maksimal të secilit nxënës.","source":"Plani Zhvillimor i Shkollës 2021–2024"}'::jsonb) on conflict (key) do nothing;
