insert into public.site_content (key, value) values ('intro_de', '{"heading":"Eine Schule, die auf Sprache baut.","body":"Seit 1990 hat die Schule einen sprachlichen Schwerpunkt. Heute ist sie ein Gymnasium für Sozial- und Sprachwissenschaften und seit dem Schuljahr 2002–2003 Teil des Programms Deutsches Sprachdiplom (DSD).","vision":"Eine leistungsstarke und inklusive Schule zu werden.","mission":"Zur bestmöglichen Entwicklung jeder Schülerin und jedes Schülers beizutragen.","source":"Schulentwicklungsplan 2021–2024"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('history_de', '[{"period":"Anfänge","title":"Im Gebäude der Normalschule","text":"Die Schule begann in den Räumen der ehemaligen Normalschule in Prishtina."},{"period":"Danach","title":"Mathematisch, dann kulturwissenschaftlich","text":"Die Schule wechselte ihr Profil: zuerst mathematisch, dann kulturwissenschaftlich."},{"period":"1990","title":"Philologisches Gymnasium","text":"Die Schule erhält einen sprachlichen Schwerpunkt."},{"period":"2002–2003","title":"Deutsches Sprachdiplom","text":"Die Arbeit im Programm Deutsches Sprachdiplom (DSD) beginnt."},{"period":"2012–2013","title":"Neues Gebäude","text":"Der Unterricht zieht in die Straße \"Remzi Salihu\" Nr. 61."},{"period":"2021–2022","title":"Sozial- und Sprachwissenschaften","text":"Per Beschluss des Bildungsministeriums (Nr. 2-854) Gymnasium für Sozial- und Sprachwissenschaften."}]'::jsonb) on conflict (key) do nothing;
