insert into public.site_content (key, value) values ('student_info_de', '{"heading":"Alles, was Schüler wissen müssen.","items":[{"title":"Schülerrat","body":"Vorsitzende im Schuljahr 2026–2027 ist Ana Arifi (XII/1).","verification":"verified"},{"title":"Deutsches Sprachdiplom","body":"Das DSD-Programm umfasst jetzt alle Jahrgänge.","verification":"verified"},{"title":"Bibliothek","body":"Die Öffnungszeiten werden hier veröffentlicht.","verification":"verified"},{"title":"Stundenplan","body":"Wird von der Schulverwaltung veröffentlicht.","verification":"pending"},{"title":"Schuljahreskalender","body":"Halbjahre und Ferien folgen nach Bestätigung.","verification":"pending"},{"title":"Staatliche Matura","body":"Termine erscheinen unter Mitteilungen.","verification":"pending"}]}'::jsonb) on conflict (key) do nothing;
