insert into public.programs (slug, name, name_de, short_name, short_name_de, tagline, tagline_de, summary, summary_de, overview, overview_de, outcomes, pathways, grades, grades_de, cover_url, sort_order, verification, source_note, source_note_de, status, published_at) values ('shkencat-shoqerore-gjuhesore', 'Gjimnazi i shkencave shoqërore-gjuhësore', 'Gymnasium für Sozial- und Sprachwissenschaften', 'Shoqëror-gjuhësor', 'Sozial- und Sprachwissenschaften', 'Gjuhët, shoqëria dhe mendimi kritik.', 'Sprachen, Gesellschaft und kritisches Denken.', 'Profili i shkollës që nga 2021–2022: gjuhët dhe shkencat shoqërore në qendër.', 'Das Profil der Schule seit 2021–2022: Sprachen und Sozialwissenschaften im Mittelpunkt.', 'Me vendim të MASHTI-t (nr. 2-854), shkolla funksionon si gjimnaz i shkencave shoqërore-gjuhësore, mbi traditën e saj filologjike që nga viti 1990. Mësohen shqipja dhe gjuhët e huaja, krahas shkencave shoqërore, historisë, psikologjisë, matematikës, shkencave natyrore, arteve, edukatës fizike dhe TIK-ut.', 'Per Beschluss des Bildungsministeriums (Nr. 2-854) ist die Schule ein Gymnasium für Sozial- und Sprachwissenschaften und baut auf ihrer philologischen Tradition seit 1990 auf. Unterrichtet werden Albanisch und Fremdsprachen sowie Sozialwissenschaften, Geschichte, Psychologie, Mathematik, Naturwissenschaften, Kunst, Sport und Informatik.', '{}'::text[], '{}'::text[], 'Klasat X–XII', 'Klassen 10–12', '/media/vizite-ore-mesimi.webp', 1, 'verified', 'Plani Zhvillimor i Shkollës 2021–2024', 'Schulentwicklungsplan 2021–2024', 'published', '2025-09-01T08:00:00Z') on conflict (slug) do nothing;
insert into public.programs (slug, name, name_de, short_name, short_name_de, tagline, tagline_de, summary, summary_de, overview, overview_de, outcomes, outcomes_de, pathways, pathways_de, grades, grades_de, cover_url, sort_order, verification, source_note, source_note_de, status, published_at) values ('diploma-gjermane', 'Programi i Diplomës Gjermane (DSD)', 'Deutsches Sprachdiplom (DSD)', 'Diploma Gjermane', 'Deutsches Sprachdiplom', 'Gjermanishtja, me partnerë në Gjermani.', 'Deutsch, mit Partnern in Deutschland.', 'Në shkollë që nga 2002–2003. Tani përfshin nxënësit e çdo gjenerate.', 'An der Schule seit 2002–2003. Jetzt für alle Jahrgänge.', 'Shkolla punon në Programin e Diplomës Gjermane që nga viti shkollor 2002–2003. Tani, për herë të parë, përfshihen nxënësit e çdo gjenerate. Programi mbështetet nga ZfA dhe Ambasada Gjermane në Kosovë, me koordinatoren e DSD për Kosovë, znj. Cornelia Menner.', 'Die Schule arbeitet seit dem Schuljahr 2002–2003 im Programm Deutsches Sprachdiplom. Erstmals sind jetzt alle Jahrgänge einbezogen. Unterstützt wird das Programm von der ZfA und der Deutschen Botschaft im Kosovo, mit der DSD-Koordinatorin für Kosovo, Frau Cornelia Menner.', array['Tekste të gjermanishtes dhe mjete didaktike për të gjithë nxënësit, nga 2025–2026', 'Seminare dhe vizita në Gjermani', 'Trajnime dhe certifikata për mësimdhënëset e gjermanishtes']::text[], array['Deutschlehrbücher und Lehrmaterial für alle Schüler ab 2025–2026', 'Seminare und Besuche in Deutschland', 'Fortbildungen und Zertifikate für die Deutschlehrerinnen']::text[], array['Certifikatë e vlefshme që lehtëson punësimin, për nxënësit që kualifikohen', 'Mundësi studimi dhe orientimi në karrierë']::text[], array['Ein anerkanntes Zertifikat, das den Berufseinstieg erleichtert, für alle, die sich qualifizieren', 'Perspektiven für Studium und Berufsorientierung']::text[], 'Klasat X–XII', 'Klassen 10–12', '/media/gjermani-educamp-grupi.webp', 2, 'verified', 'Njoftimet zyrtare të shkollës', 'Offizielle Mitteilungen der Schule', 'published', '2025-09-01T08:00:00Z') on conflict (slug) do nothing;
