insert into public.clubs (slug, name, name_de, summary, summary_de, description, description_de, meeting_info, cover_url, is_media_club, sort_order, verification, status, published_at) values ('klubi-i-medias', 'Klubi i Medias', 'Medienclub', 'Video, podkaste dhe gazetari nga nxënësit.', 'Video, Podcasts und Journalismus von Schülern.', 'Nxënësit filmojnë, montojnë, intervistojnë dhe publikojnë. Ekipi, takimet dhe produksionet publikohen nga mentorët e klubit.', 'Schüler filmen, schneiden, interviewen und veröffentlichen. Team, Treffen und Produktionen veröffentlichen die Betreuer des Clubs.', null, null, true, 1, 'pending', 'published', '2025-09-01T08:00:00Z') on conflict (slug) do nothing;
insert into public.news (slug, title, title_de, excerpt, excerpt_de, body, body_de, category, category_de, cover_url, cover_alt, featured, author_name, show_date, gallery, source_url, status, published_at) values ('keshilli-i-nxenesve-2026-2027', 'Ana Arifi, kryetare e Këshillit të Nxënësve', 'Ana Arifi leitet den Schülerrat', 'Me 100% të votave, u zgjodh kryesia e Këshillit të Nxënësve për vitin 2026–2027.', 'Mit 100 % der Stimmen wurde der Vorstand des Schülerrats für 2026–2027 gewählt.', 'Kryesia e Rinisë Shkollore organizoi takimin për zgjedhjen e Këshillit të Nxënësve të Shkollës (KNSH) për vitin shkollor 2026–2027.

Me 100% të votave të të pranishmëve, **Ana Arifi (XII/1)** u zgjodh kryetare.

## Këshilli i ngushtë

- Ana Arifi, XII/1, kryetare
- Sara Zeqiri, XII/5, sekretare
- Zyhra Fejzullahu, XII/6, arkatare

Procesin e mbikëqyrën prof. Kushtrim Bekteshi dhe prof. Ilir Bekteshi.', 'Der Vorstand der Schülerschaft lud zur Wahl des Schülerrats (KNSH) für das Schuljahr 2026–2027 ein.

Mit 100 % der Stimmen der Anwesenden wurde **Ana Arifi (XII/1)** zur Vorsitzenden gewählt.

## Der Vorstand

- Ana Arifi, XII/1, Vorsitzende
- Sara Zeqiri, XII/5, Schriftführerin
- Zyhra Fejzullahu, XII/6, Kassenwartin

Die Wahl wurde von Prof. Kushtrim Bekteshi und Prof. Ilir Bekteshi begleitet.', 'Rinia shkollore', 'Schülerschaft', null, null, false, null, false, '{}'::text[], null, 'published', '2026-10-20T09:00:00Z') on conflict (slug) do nothing;
insert into public.news (slug, title, title_de, excerpt, excerpt_de, body, body_de, category, category_de, cover_url, cover_alt, featured, author_name, show_date, gallery, source_url, status, published_at) values ('vrapimi-kunder-kancerit-te-gjirit', 'Vrapojmë kundër kancerit të gjirit', 'Wir laufen gegen Brustkrebs', 'Nxënëset tona iu bashkuan vrapimit humanitar të Kryeqytetit.', 'Unsere Schülerinnen liefen beim Benefizlauf der Hauptstadt mit.', 'Nxënëset e gjimnazit iu bashkuan iniciativës "Vrapim në luftë kundër kancerit të gjirit" të Drejtorisë së Shëndetësisë së Kryeqytetit, në muajin e ndërgjegjësimit.

I përkrahën drejtori Shemsedin Beqiri, prof. Valbona Sopi dhe prof. Valbona Avdiu.

Prej disa vitesh, gjimnazi del në përkrahje publike të grave të prekura nga kanceri i gjirit.', 'Unsere Schülerinnen nahmen am Lauf "Gemeinsam gegen Brustkrebs" der Gesundheitsdirektion der Hauptstadt teil, im Monat der Brustkrebs-Aufklärung.

Unterstützt wurden sie von Direktor Shemsedin Beqiri sowie Prof. Valbona Sopi und Prof. Valbona Avdiu.

Seit mehreren Jahren setzt sich das Gymnasium öffentlich für an Brustkrebs erkrankte Frauen ein.', 'Komuniteti', 'Gemeinschaft', null, null, false, null, false, '{}'::text[], null, 'published', '2026-10-10T09:00:00Z') on conflict (slug) do nothing;
insert into public.news (slug, title, title_de, excerpt, excerpt_de, body, body_de, category, category_de, cover_url, cover_alt, cover_alt_de, featured, author_name, show_date, gallery, source_url, status, published_at) values ('vizita-ne-gjermani-educamp', 'Një javë në Gjermani', 'Eine Woche in Deutschland', 'Nxënësit tanë me të rinj nga vende të ndryshme, në EduCamp Summer.', 'Unsere Schüler mit Jugendlichen aus vielen Ländern beim EduCamp Summer.', 'Nxënësit tanë morën pjesë në një aktivitet ndërkombëtar në Gjermani, ku të rinj nga vende të ndryshme shkëmbyen ide dhe përvoja. Vizituan qytetin, ndoqën diskutime e prezantime dhe në fund morën certifikata.

Momenti më i veçantë: flamuri kuqezi, i shfaqur me krenari nga nxënësit tanë.

## Falënderime

- Organizatorëve: Afrim Hasani, Ibadete Hasani, Egzona Ukshini-Mustafa, Halit Berisha (EduCamp, sponsor) dhe Shqipe Gara-Berisha, mësuese e gjermanishtes në shkollën shqipe në Gjermani
- Mbështetësve të programeve DSD dhe ZfA, Ambasadës Gjermane në Kosovë dhe znj. Catalina Heine
- Znj. Kerstin Zielosko nga Ministria gjermane e Arsimit
- Koordinatores së DSD për Kosovë, znj. Cornelia Menner

Prof. Shkëndije Muslijaj i përgatiti dhe i shoqëroi nxënësit gjatë gjithë javës.', 'Unsere Schülerinnen und Schüler nahmen in Deutschland an einer internationalen Veranstaltung teil, bei der Jugendliche aus verschiedenen Ländern Ideen und Erfahrungen austauschten. Sie besichtigten die Stadt, verfolgten Diskussionen und Präsentationen und erhielten zum Abschluss Zertifikate.

Ein besonderer Moment: die rot-schwarze Flagge, die unsere Schüler mit großem Stolz zeigten.

## Wir danken

- den Organisatoren: Afrim Hasani, Ibadete Hasani, Egzona Ukshini-Mustafa, Halit Berisha (EduCamp, Sponsor) und Shqipe Gara-Berisha, Deutschlehrerin an der albanischen Schule in Deutschland
- den Unterstützern des DSD- und des ZfA-Programms, der Deutschen Botschaft im Kosovo und Frau Catalina Heine
- Frau Kerstin Zielosko vom deutschen Bildungsministerium
- der DSD-Koordinatorin für Kosovo, Frau Cornelia Menner

Prof. Shkëndije Muslijaj hat die Schüler vorbereitet und die ganze Woche begleitet.', 'Diploma Gjermane', 'Deutsches Sprachdiplom', '/media/gjermani-educamp-grupi.webp', 'Nxënësit tanë me pjesëmarrës të tjerë në Gjermani.', 'Unsere Schüler mit weiteren Teilnehmenden in Deutschland.', true, null, false, array['/media/gjermani-educamp-skena.webp']::text[], null, 'published', '2026-09-25T09:00:00Z') on conflict (slug) do nothing;
insert into public.news (slug, title, title_de, excerpt, excerpt_de, body, body_de, category, category_de, cover_url, cover_alt, featured, author_name, show_date, gallery, source_url, status, published_at) values ('trajnim-me-play-international', '5.000 € për një projekt kundër diskriminimit', '5.000 € für ein Projekt gegen Diskriminierung', 'Pesë nxënës në trajnimin e Play International. Avdyl Zeqiri, lider grupi.', 'Fünf Schüler bei der Schulung von Play International. Avdyl Zeqiri leitet eine Gruppe.', 'Avdyl Zeqiri, Blerta Kameri, Ana Arifi, Armela Saraçi dhe Ari Thaçi morën pjesë në një trajnim njëditor të Play International, në Hotel Sirius.

Grupi u përkrah me një buxhet prej **5.000 €** për projekte me temën e diskriminimit. Avdyl Zeqiri u përzgjodh lider i njërit prej grupeve.

Projekti zbatohet gradualisht, me synim ndikim afatgjatë në komunitet.', 'Avdyl Zeqiri, Blerta Kameri, Ana Arifi, Armela Saraçi und Ari Thaçi nahmen an einer eintägigen Schulung von Play International im Hotel Sirius teil.

Die Gruppe erhielt ein Budget von **5.000 €** für Projekte zum Thema Diskriminierung. Avdyl Zeqiri wurde zum Leiter einer der Gruppen gewählt.

Das Projekt wird schrittweise umgesetzt und soll langfristig in die Gemeinschaft wirken.', 'Projekte', 'Projekte', null, null, false, null, false, '{}'::text[], null, 'published', '2026-05-15T09:00:00Z') on conflict (slug) do nothing;
insert into public.news (slug, title, title_de, excerpt, excerpt_de, body, body_de, category, category_de, cover_url, cover_alt, featured, author_name, show_date, gallery, source_url, status, published_at) values ('regjistrimi-ne-etwinning', 'Gjimnazi hyn në eTwinning', 'Das Gymnasium ist jetzt bei eTwinning', 'Platforma evropiane e edukimit hap rrugën për projekte të përbashkëta dhe Erasmus+.', 'Die europäische Bildungsplattform öffnet den Weg zu gemeinsamen Projekten und Erasmus+.', 'Në prani të koordinatores së Programit të Diplomës Gjermane, znj. Cornelia Menner, dhe koordinatorit të eTwinning për Kosovë, z. Genc Pilinxhurka, gjimnazi u regjistrua në eTwinning.

- Platforma u themelua në 2005; Kosova u anëtarësua në 2024
- Rreth 1.000 institucione nga 15 komuna janë pjesë e saj
- Partneritete me shkolla nga 45 shtete dhe mbi 1 milion mësimdhënës

Qëllimi: projekte të përbashkëta që hapin rrugën drejt Erasmus+.', 'Im Beisein der DSD-Koordinatorin Frau Cornelia Menner und des eTwinning-Koordinators für Kosovo, Herrn Genc Pilinxhurka, hat sich das Gymnasium bei eTwinning registriert.

- Die Plattform wurde 2005 gegründet; Kosovo ist seit 2024 dabei
- Rund 1.000 Einrichtungen aus 15 Gemeinden sind beteiligt
- Partnerschaften mit Schulen aus 45 Ländern und über einer Million Lehrkräften

Das Ziel: gemeinsame Projekte als Weg zu Erasmus+.', 'Ndërkombëtare', 'International', null, null, false, null, false, '{}'::text[], null, 'published', '2025-11-10T09:00:00Z') on conflict (slug) do nothing;
insert into public.news (slug, title, title_de, excerpt, excerpt_de, body, body_de, category, category_de, cover_url, cover_alt, featured, author_name, show_date, gallery, source_url, status, published_at) values ('seminari-i-zfa-ne-bon', 'Kosova përfaqësohet nga ne në Bon', 'Wir vertreten Kosovo in Bonn', '27–31 janar 2025: seminari i ZfA në Bon, me nxënësit tanë.', '27.–31. Januar 2025: ZfA-Seminar in Bonn, mit unseren Schülern.', 'Nga 27 deri më 31 janar 2025, gjimnazi ynë përfaqësoi Kosovën në seminarin e ZfA (Zentralstelle für das Auslandsschulwesen) në Bon të Gjermanisë.

Përzgjedhja ndër shkollat më të mira të rajonit është mirënjohje për punën e nxënësve dhe mësimdhënësve.

## Përfaqësuesit

- Jeta Sopi
- Ilir Berisha
- Melika Morina
- Enkelea Berisha

Të shoqëruar nga prof. Shkëndije Muslijaj.', 'Vom 27. bis 31. Januar 2025 vertrat unser Gymnasium Kosovo beim Seminar der ZfA (Zentralstelle für das Auslandsschulwesen) in Bonn.

Die Auswahl unter den besten Schulen der Region ist eine Anerkennung für die Arbeit von Schülern und Lehrkräften.

## Unsere Teilnehmenden

- Jeta Sopi
- Ilir Berisha
- Melika Morina
- Enkelea Berisha

Begleitet von Prof. Shkëndije Muslijaj.', 'Diploma Gjermane', 'Deutsches Sprachdiplom', null, null, false, null, false, '{}'::text[], 'https://www.auslandsschulwesen.de/zfa-de/die-zfa/aktuelle-meldungen/medienkompetenz-hautnah-schuelerinnen-und-schueler-vom-2783932', 'published', '2025-01-31T09:00:00Z') on conflict (slug) do nothing;
insert into public.news (slug, title, title_de, excerpt, excerpt_de, body, body_de, category, category_de, cover_url, cover_alt, featured, author_name, show_date, gallery, source_url, status, published_at) values ('programi-i-diplomes-gjermane-pasurohet', 'Diploma Gjermane, për çdo gjeneratë', 'Das Sprachdiplom für alle Jahrgänge', 'Koordinatori rajonal i DSD, Richard Purschwitz, prezantoi çfarë vjen për nxënësit tanë.', 'DSD-Regionalkoordinator Richard Purschwitz stellte vor, was auf unsere Schüler zukommt.', 'Koordinatori rajonal i Programit të Diplomës Gjermane, z. Richard Purschwitz, vizitoi gjimnazin dhe prezantoi zhvillimet e programit në rajon dhe në Kosovë.

## Çfarë vjen

- Nga 2025–2026: tekste të gjermanishtes dhe mjete didaktike për të gjithë nxënësit
- Trajnime dhe certifikata për mësimdhënëset e gjermanishtes
- Për gjeneratën e parë që testohet: certifikatë e vlefshme që lehtëson punësimin

Programi zhvillohet në shkollë që nga 2002–2003. Tani, për herë të parë, përfshin nxënësit e çdo gjenerate.', 'Der Regionalkoordinator des Deutschen Sprachdiploms, Herr Richard Purschwitz, besuchte das Gymnasium und stellte die Entwicklung des Programms in der Region und im Kosovo vor.

## Was kommt

- Ab 2025–2026: Deutschlehrbücher und Lehrmaterial für alle Schüler
- Fortbildungen und Zertifikate für die Deutschlehrerinnen
- Für den ersten geprüften Jahrgang: ein anerkanntes Zertifikat, das den Berufseinstieg erleichtert

Das Programm läuft an der Schule seit 2002–2003. Jetzt umfasst es erstmals alle Jahrgänge.', 'Diploma Gjermane', 'Deutsches Sprachdiplom', null, null, false, null, false, '{}'::text[], null, 'published', '2024-12-10T09:00:00Z') on conflict (slug) do nothing;
